// Bytecode Bouncer - IPv4 packet parser and rule engine
// POST JSON to the Webhook with packetHex, allowedProtocols, blockedPorts, blockedIPs.

const input = $input.first().json;
const body = input.body ?? input;

function reject(message) {
  return [{ json: { status: "REJECT", reason: message, packet: null } }];
}

const hexText = String(body.packetHex ?? "").replace(/0x/gi, "").replace(/[\s:]/g, "");
if (!hexText || !/^[0-9a-f]+$/i.test(hexText) || hexText.length % 2 !== 0) {
  return reject("Provide packetHex as an even-length hexadecimal string.");
}

const bytes = Buffer.from(hexText, "hex");
if (bytes.length < 20) return reject("Packet is too short for an IPv4 header.");

const version = bytes[0] >> 4;
const ihl = (bytes[0] & 0x0f) * 4;
if (version !== 4) return reject("Only IPv4 packets are supported.");
if (ihl < 20 || bytes.length < ihl) return reject("Invalid IPv4 header length.");

const totalLength = bytes.readUInt16BE(2);
if (totalLength < ihl || totalLength > bytes.length) {
  return reject("IPv4 total length is inconsistent with supplied bytes.");
}

const protocolNumber = bytes[9];
const protocolNames = { 1: "ICMP", 6: "TCP", 17: "UDP" };
const protocol = protocolNames[protocolNumber] ?? `UNKNOWN_${protocolNumber}`;
const ip = (offset) => [...bytes.subarray(offset, offset + 4)].join(".");
const sourceIP = ip(12);
const destinationIP = ip(16);
const ttl = bytes[8];

let sourcePort = null;
let destinationPort = null;
if (protocolNumber === 6 || protocolNumber === 17) {
  const minHeader = protocolNumber === 6 ? 20 : 8;
  if (totalLength < ihl + minHeader) return reject("Packet is too short for its TCP/UDP header.");
  sourcePort = bytes.readUInt16BE(ihl);
  destinationPort = bytes.readUInt16BE(ihl + 2);
}

const allowedProtocols = Array.isArray(body.allowedProtocols)
  ? body.allowedProtocols.map(x => String(x).toUpperCase())
  : ["TCP", "UDP", "ICMP"];
const blockedPorts = Array.isArray(body.blockedPorts)
  ? body.blockedPorts.map(Number)
  : [23, 445];
const blockedIPs = Array.isArray(body.blockedIPs)
  ? body.blockedIPs.map(String)
  : [];

const packet = {
  version,
  headerLengthBytes: ihl,
  totalLengthBytes: totalLength,
  packetBytesReceived: bytes.length,
  ttl,
  protocol,
  sourceIP,
  destinationIP,
  sourcePort,
  destinationPort
};

let status = "ALLOW";
let reason = "Packet passed all configured filtering rules.";

if (blockedIPs.includes(sourceIP) || blockedIPs.includes(destinationIP)) {
  status = "BLOCK";
  reason = "Source or destination IP is in the blocked IP list.";
} else if (!allowedProtocols.includes(protocol)) {
  status = "BLOCK";
  reason = "Protocol is not enabled in the filtering policy.";
} else if (
  (sourcePort !== null && blockedPorts.includes(sourcePort)) ||
  (destinationPort !== null && blockedPorts.includes(destinationPort))
) {
  status = "BLOCK";
  reason = "Source or destination port is blocked.";
}

return [{
  json: {
    status,
    reason,
    packet,
    inspectedAt: new Date().toISOString()
  }
}];
